draw:
var g = p.gamma;
var b = Math.sqrt(Math.max(0, 1 - 1 / (g * g)));
var th = p.star * Math.PI / 180;
var m = 135.0;

var a1 = Math.atan2(Math.sin(th), g * (Math.cos(th) + b));
var a2 = Math.atan2(Math.sin(th), g * (-Math.cos(th) + b));
var open = (a1 + a2) * 180 / Math.PI;
var E1 = 0.5 * m * g * (1 + b * Math.cos(th));
var E2 = 0.5 * m * g * (1 - b * Math.cos(th));

var cx = W * 0.46, cy = H * 0.55;
var L = Math.min(W * 0.42, H * 0.40);

ctx.font = '12px ui-sans-serif, system-ui, sans-serif';
ctx.lineWidth = 1;

// flight axis
ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(20, cy); ctx.lineTo(W - 14, cy); ctx.stroke();
ctx.setLineDash([]);

var cycle = 3.2;
var ph = (t % cycle) / cycle;

function arrow(x, y, dx, dy, col, wid) {
  ctx.strokeStyle = col; ctx.lineWidth = wid;
  ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + dx, y + dy); ctx.stroke();
  var len = Math.sqrt(dx * dx + dy * dy);
  if (len < 1) return;
  var ux = dx / len, uy = dy / len;
  ctx.beginPath();
  ctx.moveTo(x + dx, y + dy);
  ctx.lineTo(x + dx - 8 * ux + 4 * uy, y + dy - 8 * uy - 4 * ux);
  ctx.lineTo(x + dx - 8 * ux - 4 * uy, y + dy - 8 * uy + 4 * ux);
  ctx.closePath();
  ctx.fillStyle = col; ctx.fill();
}

if (ph < 0.45) {
  // incoming pion
  var frac = ph / 0.45;
  var px = 26 + (cx - 26) * frac;
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(px, cy, 7, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = C.ink;
  ctx.fillText('pion, gamma = ' + g.toFixed(2), 24, cy - 16);
} else {
  var f2 = (ph - 0.45) / 0.55;
  ctx.fillStyle = C.faint;
  ctx.beginPath(); ctx.arc(cx, cy, 3, 0, Math.PI * 2); ctx.fill();
  arrow(cx, cy, L * f2 * Math.cos(a1), -L * f2 * Math.sin(a1), C.accent, 2);
  arrow(cx, cy, L * f2 * Math.cos(a2), L * f2 * Math.sin(a2), C.figure, 2);
  ctx.fillStyle = C.accent;
  ctx.fillText(E1.toFixed(1) + ' MeV', cx + L * 0.72 * Math.cos(a1), cy - L * 0.72 * Math.sin(a1) - 8);
  ctx.fillStyle = C.figure;
  ctx.fillText(E2.toFixed(1) + ' MeV', cx + L * 0.72 * Math.cos(a2), cy + L * 0.72 * Math.sin(a2) + 16);
}

// opening-angle wedge
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.arc(cx, cy, 34, -a1, a2); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText(open.toFixed(2) + ' deg', cx + 40, cy + 4);
ctx.fillText('direction of flight', W - 130, cy - 10);

var minOpen = 2 * Math.asin(Math.min(1, 1 / g)) * 180 / Math.PI;
out.note = 'opening angle ' + open.toFixed(2) + ' deg;  smallest possible for this gamma is ' + minOpen.toFixed(2) + ' deg (emission sideways in the pion frame); photon energies ' + E1.toFixed(1) + ' and ' + E2.toFixed(1) + ' MeV';
